return [
  'judul' => 'LEMBAR INFORMASI UNTUK CALON SUBJEK PENELITIAN',
  'bagian' => [
    ['judul' => 'Pembuka', 'isi' => [['p', 'Bapak/Ibu/Saudara yang kami hormati, kami mengundang Anda ikut serta dalam sebuah penelitian. Mohon baca lembar ini dengan saksama dan tanyakan apa pun yang belum jelas. Anda tidak harus memutuskan hari ini; Anda diberi waktu sekurang-kurangnya 24 jam untuk berpikir dan berbicara dengan keluarga atau orang lain.']]],
    ['judul' => '1. Kegiatan ini adalah penelitian: latar belakang dan tujuan', 'isi' => [['p', 'Judul: Pembelajaran Mendalam Bergerbang Hierarkis untuk Prediksi Kantuk Pengemudi Akibat Kelelahan Secara Real-Time: Pendekatan Fusi Tri-Modal. Pengemudi kendaraan taktis sering lelah dan mengantuk akibat guncangan kendaraan, udara kabin, dan lamanya mengemudi. Penelitian ini bertujuan membuat sistem yang dapat memperkirakan tingkat kantuk pengemudi secara otomatis, tanpa alat yang mengganggu, dengan menggabungkan data getaran kendaraan, suhu dan CO₂ kabin, detak jantung, dan gerakan mata. Sistem ini kelak dapat dipakai untuk memberi peringatan dini agar kecelakaan dapat dicegah.']]],
    ['judul' => '2. Mengapa Anda dianggap cocok', 'isi' => [['p', 'Anda diundang karena Anda pengemudi aktif kendaraan MTV atau MPV, berusia 18 tahun ke atas, memiliki SIM yang sah dan pengalaman mengemudikan kendaraan tersebut minimal 6 bulan, serta dinyatakan laik mengemudi. Anda tidak dapat ikut bila memiliki gangguan tidur atau penyakit jantung yang sudah didiagnosis, rutin minum obat yang membuat mengantuk, sedang cedera punggung/leher/bahu, punya gangguan kelopak mata/penglihatan yang tidak terkoreksi, alergi terhadap bahan tali/perekat sensor, atau merupakan bawahan langsung peneliti.']]],
