    ['judul' => '14. Petugas penanggung jawab medis', 'isi' => [['p', 'Nama : merujuk pada ijin yang dikeluarkan oleh mitra'], ['p', 'Alamat : RS. PINDAD (Lokasi yang terdekat dengan Lokasi uji)'], ['p', 'Telepon : merujuk pada ijin yang dikeluarkan oleh mitra']]],
    ['judul' => '15. Ketua peneliti', 'isi' => [['p', 'Nama : Periyadi, S.T., M.T.'], ['p', 'Alamat : Jl. Mars Dirgahayu No/kav. 7 Rt 01 Rw 10 kel. Cibeunying Kec. Cimenyan Kab bandung 40191'], ['p', 'Telepon : 085101616015'], ['p', 'Email : pperiyadi@student.telkomuniversity.ac.id']]],
